_RETRYABLE_YFINANCE_: tuple[type[Exception], ...] = (ConnectionError, TimeoutError, OSError, YFRateLimitError)

def _is_rate_limit_error(exc: BaseException) -> bool:
    return isinstance(exc, YFRateLimitError)

def _create_retryable_er(action: str, exc: BaseException, details: dict[str, Any]) -> str:
    if _is_rate_limit_error(exc):
        message = f'Rate limit reached while {action}. Try again later.'
    else:
        message = f'Temporary network issue while {action}. Try again later.'
    return create_error_respons(message, error_code='NETWORK_ERROR', details={**details, 'exception': str(exc)})

@mcp.tool(name='yfinance_get_ticker_info', annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
async def get_ticker_info(symbol: Annotated[str, Field(description="Stock ticker symbol (e.g., 'AAPL', 'GOOGL', 'MSFT')")]) -> str:
    try:
        ticker = await asyncio.to_thread(yf.Ticker, symbol)
        info = await asyncio.to_thread(lambda: ticker.info)
    except _RETRYABLE_YFINANCE_ as exc:
        return _create_retryable_er(f"fetching ticker info for '{symbol}'", exc, {'symbol': symbol})
    except Exception as exc:
        return create_error_respons(f"Failed to fetch ticker info for '{symbol}'. Verify the symbol is correct and try again.", error_code='API_ERROR', details={'symbol': symbol, 'exception': str(exc)})
    if not info:
        return create_error_respons(f"No information available for symbol '{symbol}'. The symbol may be invalid or delisted. Try searching for the company name using the 'yfinance_search' tool to find the correct symbol.", error_code='INVALID_SYMBOL', details={'symbol': symbol})
    for key, value in list(info.items()):
        if not isinstance(key, str):
            continue
        if not isinstance(value, int | float):
            continue
        if key.lower().endswith(('date', 'start', 'end', 'timestamp', 'time', 'quarter')):
            try:
                info[key] = datetime.fromtimestamp(value).strftime('%Y-%m-%d %H:%M:%S')
            except Exception as exc:
                logger.error('Unable to convert {}: {} to datetime: {}', key, value, exc)
    return dump_json(info)

